package com.minecraftcodex.casino.gui;
import com.minecraftcodex.casino.Main; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.inventory.*; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import org.bukkit.scheduler.BukkitRunnable; import java.util.*;
public final class CasinoGui implements Listener {private final Main p;private final Map<UUID,Double> bets=new HashMap<>();private final Map<UUID,List<Integer>> hands=new HashMap<>();private final Random random=new Random();private final Set<UUID> poker=new HashSet<>();
 public CasinoGui(Main p){this.p=p;} public void setBet(Player x,double amount){if(amount<p.getConfig().getDouble("bets.minimum")||amount>p.getConfig().getDouble("bets.maximum")){x.sendMessage(title("invalid-bet").replace("{min}",String.valueOf(p.getConfig().getDouble("bets.minimum"))).replace("{max}",String.valueOf(p.getConfig().getDouble("bets.maximum"))));return;}bets.put(x.getUniqueId(),amount);x.sendMessage(title("bet-set").replace("{amount}",String.format(Locale.ROOT,"%.2f",amount)));} public boolean open(Player pl,String game){return switch(game.toLowerCase(Locale.ROOT)){case "slots"->{slots(pl);yield true;}case "blackjack"->{blackjack(pl);yield true;}case "roulette"->{roulette(pl);yield true;}case "poker"->{poker(pl);yield true;}case "truthlie","truth-or-lie"->{truth(pl);yield true;}default->false;};}
 private String title(String key){return ChatColor.translateAlternateColorCodes('&',p.message(key));} private void slots(Player x){Inventory i=Bukkit.createInventory(x,27,title("slots-title"));fill(i,Material.BLACK_STAINED_GLASS_PANE);i.setItem(11,symbol("CHERRY"));i.setItem(13,symbol("LEMON"));i.setItem(15,symbol("SEVEN"));i.setItem(22,item(Material.EMERALD,"&aSpin / Bet: "+bet(x)));x.openInventory(i);} private void blackjack(Player x){hands.put(x.getUniqueId(),new ArrayList<>(List.of(card(),card())));drawBlackjack(x);}private void drawBlackjack(Player x){Inventory i=Bukkit.createInventory(x,27,title("blackjack-title"));fill(i,Material.GREEN_STAINED_GLASS_PANE);List<Integer> h=hands.get(x.getUniqueId());for(int n=0;n<h.size();n++)i.setItem(10+n,cardItem(h.get(n)));i.setItem(21,item(Material.LIME_DYE,"&aHit"));i.setItem(22,item(Material.RED_DYE,"&cStand"));i.setItem(23,item(Material.GOLD_INGOT,"&6Double"));x.openInventory(i);}
 private void roulette(Player x){Inventory i=Bukkit.createInventory(x,54,title("roulette-title"));for(int n=0;n<=36;n++)i.setItem(n, item(n==0?Material.LIME_CONCRETE:(red(n)?Material.RED_CONCRETE:Material.BLACK_CONCRETE),"&f"+n));i.setItem(45,item(Material.WHITE_WOOL,"&fEven"));i.setItem(46,item(Material.BLACK_WOOL,"&0Odd"));i.setItem(47,item(Material.RED_WOOL,"&cRed"));i.setItem(48,item(Material.BLACK_WOOL,"&0Black"));i.setItem(49,item(Material.EMERALD,"&aSpin / Bet: "+bet(x)));x.openInventory(i);}
 private void poker(Player x){poker.add(x.getUniqueId());Inventory i=Bukkit.createInventory(x,27,title("poker-title"));fill(i,Material.GREEN_STAINED_GLASS_PANE);i.setItem(10,cardItem(card()));i.setItem(11,cardItem(card()));i.setItem(13,item(Material.EMERALD,"&aJoin / Check"));i.setItem(14,item(Material.GOLD_INGOT,"&6Bet / Raise"));i.setItem(15,item(Material.RED_DYE,"&cFold"));i.setItem(22,item(Material.PAPER,"&ePlayers: "+poker.size()+"/6"));x.openInventory(i);}
 private void truth(Player x){Inventory i=Bukkit.createInventory(x,27,title("truthlie-title"));fill(i,Material.PURPLE_STAINED_GLASS_PANE);List<String> q=p.getConfig().getStringList("questions");i.setItem(13,item(Material.BOOK,"&f"+q.get(random.nextInt(q.size()))));i.setItem(21,item(Material.LIME_WOOL,"&aTruth"));i.setItem(23,item(Material.RED_WOOL,"&cLie"));x.openInventory(i);}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player x)||e.getCurrentItem()==null||!e.getView().getTitle().contains("Casino")&&!Set.of(title("slots-title"),title("blackjack-title"),title("roulette-title"),title("poker-title"),title("truthlie-title")).contains(e.getView().getTitle()))return;e.setCancelled(true);int slot=e.getRawSlot();String t=ChatColor.stripColor(e.getView().getTitle());if(slot>=e.getInventory().getSize())return;if(slot==22&&t.equals(ChatColor.stripColor(title("slots-title"))))spin(x);else if(t.equals(ChatColor.stripColor(title("blackjack-title"))))blackjackClick(x,slot);else if(t.equals(ChatColor.stripColor(title("roulette-title")))&&slot<=49)rouletteBet(x,slot);else if(t.equals(ChatColor.stripColor(title("truthlie-title")))&&(slot==21||slot==23))settle(x,"truthlie",slot==21?1:0,slot==21?"truth":"lie");}
 private double bet(Player x){return bets.getOrDefault(x.getUniqueId(),p.getConfig().getDouble("bets.default"));} private void spin(Player x){double b=bet(x);if(!take(x,b))return;new BukkitRunnable(){int ticks=0;public void run(){ticks+=5;Inventory i=x.getOpenInventory().getTopInventory();i.setItem(11,symbol(randSymbol()));i.setItem(13,symbol(randSymbol()));i.setItem(15,symbol(randSymbol()));if(ticks>=p.getConfig().getInt("slots.spin-ticks")){String s=randSymbol();i.setItem(11,symbol(s));i.setItem(13,symbol(s));i.setItem(15,symbol(s));double payout=b*p.getConfig().getDouble("slots.multipliers."+s,0);settlePaid(x,"slots",b,payout,payout>0?"win":"loss");cancel();}}}.runTaskTimer(p,0,5);}
 private void blackjackClick(Player x,int slot){List<Integer> h=hands.get(x.getUniqueId());if(slot==21){h.add(card());if(score(h)>21){settle(x,"blackjack",0,"loss");x.closeInventory();}else drawBlackjack(x);}else if(slot==22||slot==23){double b=bet(x)*(slot==23?2:1);if(!take(x,b))return;int dealer=17+random.nextInt(5),score=score(h);double payout=score==21?b*2.5:(score>dealer||dealer>21?b*2:score==dealer?b:0);settlePaid(x,"blackjack",b,payout,payout==b?"push":payout>0?"win":"loss");x.closeInventory();}}
 private void rouletteBet(Player x,int slot){if(slot==49){return;}double b=bet(x);if(!take(x,b))return;int ball=random.nextInt(37);boolean win=(slot<=36&&slot==ball)||(slot==45&&ball>0&&ball%2==0)||(slot==46&&ball%2==1)||(slot==47&&red(ball))||(slot==48&&ball>0&&!red(ball));settlePaid(x,"roulette",b,win?b*(slot<=36?36:2):0,win?"win":"loss");}
 private void settle(Player x,String g,double payout,String result){double b=bet(x);if(!take(x,b))return;settlePaid(x,g,b,payout,result);}private void settlePaid(Player x,String g,double b,double payout,String r){if(payout>0)p.economy().give(x,payout);p.database().history(x.getUniqueId(),g,b,payout,r);p.database().stat(x.getUniqueId(),g+"_"+r);String k=payout==b?"push":payout>b?"won":"lost";x.sendMessage(ChatColor.translateAlternateColorCodes('&',p.message("prefix")+p.message(k).replace("{amount}",String.format(Locale.ROOT,"%.2f",payout>0?payout:b))));}
 private boolean take(Player x,double b){if(b<p.getConfig().getDouble("bets.minimum")||b>p.getConfig().getDouble("bets.maximum")){x.sendMessage(title("invalid-bet").replace("{min}",String.valueOf(p.getConfig().getDouble("bets.minimum"))).replace("{max}",String.valueOf(p.getConfig().getDouble("bets.maximum"))));return false;}if(!p.economy().take(x,b)){x.sendMessage(title("no-money"));return false;}return true;} private int card(){return 1+random.nextInt(13);}private int score(List<Integer> h){int s=h.stream().mapToInt(n->n>10?10:n).sum();return s;}private ItemStack cardItem(int rank){ItemStack x=item(Material.PAPER,"&fCard "+rank);x.getItemMeta();ItemMeta m=x.getItemMeta();m.setCustomModelData(p.getConfig().getInt("custom-model-data.cards.first-card")+rank-1);x.setItemMeta(m);return x;}private String randSymbol(){return List.of("CHERRY","LEMON","SEVEN","BAR","STAR").get(random.nextInt(5));}private ItemStack symbol(String s){ItemStack x=item(Material.SUNFLOWER,"&f"+s);ItemMeta m=x.getItemMeta();m.setCustomModelData(p.getConfig().getInt("custom-model-data.slots."+s.toLowerCase()));x.setItemMeta(m);return x;}private static boolean red(int n){return Set.of(1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36).contains(n);}private static ItemStack item(Material m,String n){ItemStack x=new ItemStack(m);ItemMeta meta=x.getItemMeta();meta.setDisplayName(ChatColor.translateAlternateColorCodes('&',n));x.setItemMeta(meta);return x;}private static void fill(Inventory i,Material m){for(int n=0;n<i.getSize();n++)i.setItem(n,item(m," "));}}
